// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-03-nusach-availability-switch.spec.ts, план .qa/e2e/specs/guided-prayer.md, кейс .qa/tests/guided-prayer/GP-03-nusach-availability-switch.md
// Тикет #ecda5d38 · af824b52076b «אי-עקביות בטיפול בנוסח «ספרד / עדות המזרח»». Опора: S-33 (עדות המזרח «בקרוב», невыбираемый; смена на уровне всей молитвы).
// ОБНОВЛЕНО 21.10 (#32e3cd9a, עבר QA): пункта «עדות המזרח · בקרוב» в меню больше нет — только «אשכנזי» / «ספרדי».
import { expect, $, driver } from '@wdio/globals';
import { byText, byTextContains, byLabelStartsWith, tapText, tapLabel, expectVisibleText, pageCounter, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

/** Пункт меню «עדות המזרח» (radio с текстом «בקרוב»): Android — кликабельный предок текста, iOS — элемент с подписью. */
function edotItem() {
  return driver.isAndroid
    ? $('//*[(@clickable="true" or @checkable="true") and .//*[@text="עדות המזרח"]]')
    : $('-ios predicate string:label BEGINSWITH "עדות המזרח" OR name BEGINSWITH "עדות המזרח"');
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-03 Нусах: в меню 2 пункта (без «עדות המזרח · בקרוב»), смена на уровне всей молитвы с подтверждением и возвратом #ecda5d38 #32e3cd9a @prod-safe', async () => {
    // 1. מנחה (אשכנזי) «4 מתוך 8» — «נפילת אפים».
    await openPrayer('mincha_ashkenaz', 'מנחה');
    await goToPage(4, 8);
    expect(await pageCounter()).toBe('4 מתוך 8');
    await expectVisibleText('נפילת אפים');

    // 2. «בחירת נוסח» → список: אשכנזי отмечен ✓, ספרדי есть, «עדות המזרח»/«בקרוב» нет (#32e3cd9a, 21.10).
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await expectVisibleText('✓');
    await expectVisibleText('ספרדי');
    expect(await (await edotItem()).isExisting()).toBe(false);
    expect(await (await byTextContains('בקרוב')).isExisting()).toBe(false);

    // 3. «ספרדי» → окно → «ביטול»: прежний нусах и קטע.
    await tapText('ספרדי');
    await expectVisibleText('להחליף את התפילה לנוסח ספרד?');
    await expectVisibleText('תועבר לקטע המקביל ״נפילת אפיים״.');
    await tapText('ביטול');
    await expect(byText('להחליף את התפילה לנוסח ספרד?')).not.toBeDisplayed();
    await expectVisibleText('מנחה (אשכנזי)');
    expect(await pageCounter()).toBe('4 מתוך 8');

    // 4. Снова «ספרדי» → «החלף»: מנחה (ספרדי) «6 מתוך 11», «נפילת אפיים».
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText('ספרדי');
    await tapText('החלף');
    await expectVisibleText('מנחה (ספרדי)');
    expect(await pageCounter()).toBe('6 מתוך 11');
    await expectVisibleText('נפילת אפיים');

    // 5. Вернуть: «אשכנזי» → «החלף» → מנחה (אשכנזי) «4 מתוך 8».
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText('אשכנזי');
    await tapText('החלף');
    await expectVisibleText('מנחה (אשכנזי)');
    expect(await pageCounter()).toBe('4 מתוך 8');

    // 6. Профиль: «נוסח תפילה» = אשכנז (не изменился).
    await toHome();
    await tapLabel('מעבר לפרטים שלי');
    await scrollToText('נוסח תפילה');
    await expectVisibleText('אשכנז');
  });
});
